const save=()=>localStorage.setItem('soyo-preview-v2',JSON.stringify(demo));
async function api(path,method='GET',data){
 if(preview){
  if(path==='events')return demo.events;
  if(path==='me')return {user:demo.user,admin:demo.admin};
  if(path==='logout'){demo.user=null;demo.admin=false;save();return {ok:true}}
  if(path==='reading-notes'&&method==='GET')return window.readingNotes;
  if(path==='private-notes'&&method==='GET'){if(!demo.user)throw Error('로그인이 필요합니다.');return window.privateNotes.filter(n=>n.user_id===demo.user.id)}
  if(/^reading-notes\/.+\/comments$/.test(path)&&method==='GET')return (window.noteComments[path.split('/')[1]]||[]);
  if(!demo.user)throw Error('로그인이 필요합니다.');
  if(path==='me'&&method==='PATCH'){const nickname=String(data?.nickname||'').trim();if(nickname.length<2||nickname.length>24)throw Error('닉네임은 2~24자로 입력해 주세요.');demo.user.nickname=nickname;save();return {id:demo.user.id,nickname}}
  if(path.startsWith('admin/')&&!demo.admin)throw Error('관리자 권한이 필요합니다.');
  if(path==='applications'&&method==='GET')return demo.applications;
  if(path==='applications'){
   const event=demo.events.find(e=>e.id===data.eventId);if(!event||event.status!=='open')throw Error('신청할 수 없는 모임입니다.');
   if(demo.applications.some(a=>a.event_id===data.eventId&&a.status!=='cancelled'))throw Error('이미 신청한 모임입니다.');
   const existing=demo.applications.find(a=>a.event_id===data.eventId);if(existing){existing.status='pending';existing.depositor_name=data.depositorName||''}else demo.applications.push({id:crypto.randomUUID(),event_id:data.eventId,status:'pending',depositor_name:data.depositorName||'',created_at:new Date().toISOString()});
  }else if(path==='applications/cancel'){demo.applications.find(a=>a.id===data.id).status='cancelled'}
  else if(path==='admin/applications')return demo.applications.map(a=>({...a,users:{nickname:demo.user.nickname},events:{title:demo.events.find(e=>e.id===a.event_id)?.title}}));
  else if(path==='admin/applications/status')demo.applications.find(a=>a.id===data.id).status=data.status;
  else if(path==='admin/events/status')demo.events.find(e=>e.id===data.id).status=data.status;
  else if(path==='reviews'&&method==='GET')return publicReviews;
  else if(path==='reviews/mine')return myReviews;
  else if(path==='reviews'&&method==='POST'){const review={...data,id:crypto.randomUUID(),user_id:demo.user.id,created_at:new Date().toISOString(),users:{nickname:demo.user.nickname},events:{title:demo.events.find(e=>e.id===data.eventId)?.title}};publicReviews.unshift(review);myReviews.unshift(review);return review}
  else if(path.startsWith('reviews/')){const id=path.split('/').at(-1),i=publicReviews.findIndex(r=>r.id===id&&r.user_id===demo.user.id);if(i<0)throw Error('후기를 찾을 수 없습니다.');if(method==='DELETE'){publicReviews.splice(i,1);myReviews=myReviews.filter(r=>r.id!==id)}else Object.assign(publicReviews[i],data);return {ok:true}}
  else if(path.startsWith('book-reviews/')){const id=path.split('/').at(-1),i=(window.bookReviews||[]).findIndex(r=>r.id===id&&r.user_id===demo.user.id);if(i<0)throw Error('서평을 찾을 수 없습니다.');if(method==='DELETE')window.bookReviews.splice(i,1);else Object.assign(window.bookReviews[i],{book_title:data.title,body:data.body});return {ok:true}}
  else if(path==='book-reviews'&&method==='POST'){const row={...data,id:crypto.randomUUID(),user_id:demo.user.id,users:{nickname:demo.user.nickname}};window.bookReviews=[row,...(window.bookReviews||[])];return row}
  else if(path==='reading-notes'&&method==='POST'){const row={...data,book_title:data.title,id:crypto.randomUUID(),user_id:demo.user.id,created_at:new Date().toISOString(),users:{nickname:demo.user.nickname}};window.readingNotes=[row,...window.readingNotes];return row}
  else if(/^reading-notes\/.+\/likes$/.test(path)&&method==='POST'){const row=window.readingNotes.find(x=>x.id===path.split('/')[1]);if(row){row.likes_count=(row.likes_count||0)+(data.liked?1:-1);row.likes_count=Math.max(0,row.likes_count);row.liked_by_me=data.liked}return {ok:true}}
  else if(/^reading-notes\/.+\/comments$/.test(path)&&method==='POST'){const id=path.split('/')[1],row={id:crypto.randomUUID(),reading_note_id:id,user_id:demo.user.id,body:data.body,created_at:new Date().toISOString(),users:{nickname:demo.user.nickname}};window.noteComments[id]=[...(window.noteComments[id]||[]),row];const note=window.readingNotes.find(x=>x.id===id);if(note)note.comments_count=(note.comments_count||0)+1;return row}
  else if(path.startsWith('reading-note-comments/')){const id=path.split('/').at(-1);for(const key of Object.keys(window.noteComments))window.noteComments[key]=window.noteComments[key].filter(x=>x.id!==id||x.user_id!==demo.user.id);return {ok:true}}
  else if(path==='private-notes'&&method==='POST'){const row={id:crypto.randomUUID(),user_id:demo.user.id,book_title:data.title||'',body:data.body,created_at:new Date().toISOString()};window.privateNotes=[row,...window.privateNotes];return row}
  else if(path.startsWith('private-notes/')){const id=path.split('/').at(-1),i=window.privateNotes.findIndex(x=>x.id===id&&x.user_id===demo.user.id);if(i<0)throw Error('비공개 기록을 찾을 수 없습니다.');if(method==='DELETE')window.privateNotes.splice(i,1);else Object.assign(window.privateNotes[i],{book_title:data.title||'',body:data.body});return {ok:true}}
  else if(path.startsWith('reading-notes/')){const id=path.split('/').at(-1),i=window.readingNotes.findIndex(r=>r.id===id&&r.user_id===demo.user.id);if(i<0)throw Error('읽기 기록을 찾을 수 없습니다.');if(method==='DELETE')window.readingNotes.splice(i,1);else Object.assign(window.readingNotes[i],{book_title:data.title,body:data.body,photos:data.photos||[]});return {ok:true}}
  else if(path.startsWith('admin/events/')){const e=demo.events.find(e=>e.id===path.split('/').at(-1));Object.assign(e,data);return e}
  else if(path==='admin/events')demo.events.push({...data,id:crypto.randomUUID(),end_time:data.end,status:'open'});
  save();return {ok:true};
 }
 const r=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});
 let j;try{j=await r.json()}catch{throw Error('서버에 연결하지 못했어요. 잠시 후 다시 시도해 주세요.')}
 if(!r.ok)throw Error(j.error||'요청에 실패했습니다.');return j;
}
async function loadRouteData(target=route){
 const jobs=[],ownerId=db.user?.id,userScoped=['applications','myReviews','privateNotes'];
 const add=(key,path)=>jobs.push(async()=>{
  try{
   const value=await api(path);if(userScoped.includes(key)&&db.user?.id!==ownerId)return;
   if(key==='events')db.events=value;else if(key==='applications')db.applications=value;else if(key==='adminApplications')adminApplications=value;else if(key==='publicReviews')publicReviews=value;else if(key==='myReviews')myReviews=value;else if(key==='bookReviews')window.bookReviews=value;else if(key==='readingNotes'){publicReadingNotes=value;window.readingNotes=value}else if(key==='privateNotes'){privateNotes=value;window.privateNotes=value}else if(key==='adminBookReviews')window.adminBookReviews=value
  }catch{
   if(userScoped.includes(key)&&db.user?.id!==ownerId)return;
   if(key==='events')db.events=[];else if(key==='applications')db.applications=[];else if(key==='adminApplications')adminApplications=[];else if(key==='publicReviews')publicReviews=[];else if(key==='myReviews')myReviews=[];else if(key==='bookReviews')window.bookReviews=[];else if(key==='readingNotes'){publicReadingNotes=[];window.readingNotes=[]}else if(key==='privateNotes'){privateNotes=[];window.privateNotes=[]}else if(key==='adminBookReviews')window.adminBookReviews=[]
  }
 });
 if(target==='detail'){if(db.user)add('applications','applications');add('publicReviews','reviews')}
 if(target==='my'||target==='success'){if(db.user)add('applications','applications')}
 if(target==='reviews'){add('publicReviews','reviews');add('bookReviews','book-reviews');add('readingNotes','reading-notes');if(db.user){add('myReviews','reviews/mine');add('privateNotes','private-notes')}}
 if((target==='admin'||target==='editEvent'||target==='newEvent')&&db.admin){add('events','admin/events');if(target==='admin'){add('adminApplications','admin/applications');add('publicReviews','reviews');add('adminBookReviews','admin/book-reviews')}}
 await Promise.all(jobs.map(job=>job()));if(target===route)render()
}
async function reload(){if(db.events.length&&['home','events','about','privacy','login'].includes(route))render();const [events,me]=await Promise.all([api('events'),api('me')]);try{sessionStorage.setItem('soyo-public-events',JSON.stringify({savedAt:Date.now(),events}))}catch{}if(db.user?.id!==me.user?.id){privateNotes=[];window.privateNotes=[];myReviews=[]}db={events,...me,applications:[]};render();await loadRouteData(route)}
function nav(r,id){closeModal();route=r;selected=id;const next=r+(id?'/'+id:'');if(location.hash.slice(1)!==next)location.hash=next;else render();window.scrollTo({top:0})}
window.addEventListener('hashchange',()=>{[route='home',selected]=location.hash.slice(1).split('/');render();window.scrollTo({top:0});loadRouteData(route)});
const date=s=>new Date(s).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'short'});
const time=s=>new Date(s).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false});
const label={pending:'승인 대기',confirmed:'참여 확정',waitlist:'대기 중',cancelled:'신청 취소'};
const state=e=>e.status==='soon'?'모집 예정':e.status==='closed'||new Date(e.date)<new Date()?'모집 마감':'모집 중';
const categoryInfo={literature:{name:'문학 · 고전',background:'#DCE5FC',accent:'#3456A5'},philosophy:{name:'철학 · 사유',background:'#E6DDF4',accent:'#7956A2'},meditation:{name:'명상 · 마음',background:'#DAE9DB',accent:'#3E725B'},writing:{name:'글쓰기 · 창작',background:'#F9DECF',accent:'#CB624A'},reading:{name:'원서 읽기',background:'#F5EDC8',accent:'#9F7C29'},free:{name:'자유모임',background:'#E5E5E5',accent:'#444444'}};
const categorySlug=e=>{const c=String(e?.category||'').replaceAll(' ','');return ({'문학':'literature','고전':'literature','문학·고전':'literature','철학':'philosophy','사유':'philosophy','철학·사유':'philosophy','명상':'meditation','마음':'meditation','명상·마음':'meditation','글쓰기':'writing','창작':'writing','글쓰기·창작':'writing','원서':'reading','원서읽기':'reading','원서·읽기':'reading','자유모임':'free','자유':'free'})[c]||'literature'};
const categoryTitle=e=>categoryInfo[categorySlug(e)].name;
const categoryAsset=(e,kind='card')=>`/images/categories/category-${categorySlug(e)}${kind==='card'?'-card':''}.webp`;
const theme=e=>({literature:'rose',philosophy:'blue',meditation:'sage',writing:'sand',reading:'sand',free:'blue'}[categorySlug(e)]||'sage');
const eyebrow=t=>`<div class="eyebrow">${t}</div>`;
function header(title){return `<header class="top"><button class="icon-button" aria-label="모임 목록으로" onclick="nav('events')">${icon('back')}</button><span>${esc(title)}</span><button class="icon-button" aria-label="내 소요 페이지" onclick="nav('my')">${icon('my',20)}</button></header>`}
function tabs(){return `<nav class="tabs" aria-label="주 메뉴">${[['home','home','홈'],['events','book','모임'],['reviews','about','기록'],['my','my','내 소요']].map(([r,i,t])=>`<button class="tab ${route===r||r==='events'&&route==='detail'?'active':''}" onclick="nav('${r}')" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`}
const palette=e=>[categoryInfo[categorySlug(e)].background,categoryInfo[categorySlug(e)].accent];
function book(e,large=false){return `<div class="book-art ${theme(e)} ${large?'large':''}" aria-hidden="true"><div class="book-spine"></div><span class="book-kicker">SOYO READING CLUB</span><strong>${esc(e.book)}</strong><span class="book-line"></span><span class="book-author">${esc(e.author||'함께 읽는 책')}</span><span class="book-mark">soyo.</span></div>`}
const coverLibrary={
 '이처럼 사소한 것들':{file:'small-things.jpg',edition:'이처럼 사소한 것들 · 다산책방',url:'https://www.aladin.co.kr/shop/wproduct.aspx?Itemid=329386807'},
 '요가 수트라':{file:'yoga-sutras.jpg',edition:'옥스퍼드 요가 수트라 수업 · 동글디자인',url:'https://www.yes24.com/product/goods/168848154'},
 '카라마조프가의 형제들':{file:'karamazov.jpg',edition:'카라마조프가의 형제들 1 · 민음사',url:'https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=988088'},
 '시지프 신화':{file:'sisyphus.jpg',edition:'시지프 신화 · 민음사',url:'https://www.aladin.co.kr/shop/wproduct.aspx?itemid=86074428'}
};
function coverImage(e,detail=false){const c=coverLibrary[e.book];const src=e.cover_url|| (c?`/images/${c.file}`:'');return src?`<img class="real-book-cover ${detail?'detail-book-image':''}" src="${esc(src)}" alt="${esc(e.book)} 표지" width="120" height="180" loading="${detail?'eager':'lazy'}" decoding="async" onerror="this.hidden=true;this.closest('.poster,.detail-cover')?.classList.remove('with-book-cover')">`:''}
function placeName(e){return e.place||''}
function placeAddress(e){return e.place_address||''}
function mapUrl(e){return `https://map.naver.com/p/search/${encodeURIComponent(placeAddress(e)||placeName(e))}`}
function shareSlug(e){return String(e.title||e.book||'meeting').trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-+|-+$/g,'').slice(0,48)||'meeting'}
function shareCode(e){return e.share_code||String(e.id||'').replaceAll('-','').slice(0,12).toLowerCase()}
function card(e){return `<button class="event event-row" onclick="nav('detail','${e.id}')"><span class="event-cover"><img class="event-cover-image" src="${esc(e.cover_url||categoryAsset(e))}" alt="" loading="lazy" decoding="async"></span><span class="event-info"><span class="event-badges"><span class="event-state ${state(e)==='모집 중'?'open':''}">${state(e)}</span><span class="event-category-chip" style="--category-accent:${palette(e)[1]}">${esc(categoryTitle(e))}</span></span><strong>${esc(e.book?`『${e.book}』`:e.title)}</strong><span class="event-subtitle">${esc(e.title)}</span><span class="event-meta">${icon('calendar',16)} ${esc(date(e.date))} · ${time(e.date)}</span><span class="event-meta">${icon('pin',16)} ${esc(placeName(e))}</span></span><span class="event-arrow">↗</span></button>`}
function homeCard(e){const c=coverLibrary[e.book],cover=e.cover_url||(c?`/images/${c.file}`:'');return `<button class="home-event-card" onclick="nav('detail','${e.id}')" style="--category-background:${palette(e)[0]};--category-accent:${palette(e)[1]};--category-card-image:url('${categoryAsset(e)}')"><span class="home-event-cover ${cover?'':'no-cover'}">${cover?`<img src="${esc(cover)}" alt="${esc(e.book||'모임')} 책 표지" loading="lazy" decoding="async">`:`<span aria-hidden="true">SOYO</span>`}</span><span class="home-event-info"><span class="home-event-badges"><span class="event-state open">모집 중</span><span class="event-category-chip" style="--category-accent:${palette(e)[1]}">${esc(categoryTitle(e))}</span></span><strong>${esc(e.title)}</strong><span class="home-event-book-title">${e.book?`『${esc(e.book)}』`:''}</span><span class="event-meta">${icon('calendar',17)} ${esc(date(e.date))} · ${time(e.date)}</span><span class="event-meta">${icon('pin',17)} ${esc(placeName(e))}</span></span><span class="home-event-arrow" aria-hidden="true">${icon('arrow',22)}</span></button>`}
function welcomeGuide(){return !db.user?`<section class="section welcome-section"><div class="welcome-guide"><div class="welcome-title"><span>처음 오셨나요?</span><button class="small-link" onclick="nav('login')">카카오로 시작하기 ↗</button></div>${[
  ['1','마음에 드는 모임을 골라요','책을 다 읽지 않아도 괜찮아요.'],
  ['2','무료로 신청해요','카카오 로그인 후 간편하게 신청해요.'],
  ['3','확정되면 만나요','MY에서 확인하고, 모임 전날 카카오톡으로 안내해요.']
].map(([n,t,p])=>`<div class="welcome-step"><span>${n}</span><div><b>${t}</b><p>${p}</p></div></div>`).join('')}</div></section>`:''}
function home(){const shortcuts=[['문학 · 고전','문학','book'],['철학 · 사유','철학','leaf'],['명상 · 마음','명상','lotus'],['글쓰기 · 창작','글쓰기','pencil'],['자유모임','자유모임','users']];return `<div class="home-hero-card"><header class="top home-top"><div class="brand home-brand"><span>SOYO SALON</span><small>소요살롱</small></div><div class="home-actions"><span class="home-bell" aria-hidden="true">${icon('bell',24)}</span><button class="icon" aria-label="소요살롱 소개" onclick="nav('about')">${icon('menu',24)}</button></div></header><section class="hero home-hero"><div class="hero-art" aria-hidden="true"><img src="${homeHeroImage}" alt=""></div><div class="eyebrow">逍遙 · 자유롭게 거닐다</div><h1>책에서 시작해,<br>서로의 세계를 만나는 시간.</h1><p>책을 읽고, 마음에 남은 문장을 나눕니다.<br>서로 다른 생각과 삶이 만나는 작은 모임입니다.</p></section></div><nav class="home-category-grid" aria-label="모임 카테고리 바로가기">${shortcuts.map(([label,category,ico])=>{const slug=categorySlug({category});return `<button class="home-category" style="--category-background:${categoryInfo[slug].background};--category-accent:${categoryInfo[slug].accent}" onclick="filter='${category}';nav('events')">${icon(ico,31)}<span>${label}</span></button>`}).join('')}</nav><section class="home-open-section"><div class="home-open-heading"><div><span>SOYO SALON</span><h2>지금 모집 중인 모임</h2></div><button onclick="nav('events')">모든 모임 보기 ↗</button></div><div class="home-event-list">${db.events.filter(e=>state(e)==='모집 중').slice(0,3).map(homeCard).join('')||'<p class="home-empty">지금 함께할 모임을 준비하고 있어요.</p>'}</div></section>${welcomeGuide()}`}
function empty(t){return `<div class="empty">${icon('book',32)}<p>${t}</p></div>`}
function events(){let list=db.events.filter(e=>filter==='전체'||categorySlug(e)===categorySlug({category:filter}));return `${header('함께 읽는 모임')}<section class="content">${eyebrow('FIND YOUR NEXT CHAPTER')}<h1 class="page-title">이번에는 어떤 책을<br>함께 읽어볼까요?</h1><p class="subcopy">읽고 싶은 마음만 있다면 충분해요.</p><div class="chiprow" aria-label="모임 분류">${['전체','문학','철학','명상','글쓰기','원서','자유모임'].map(c=>`<button class="chip ${filter===c?'on':''}" aria-pressed="${filter===c}" onclick="filter='${c}';render()">${c}</button>`).join('')}</div>${list.map(e=>card(e)).join('')||empty('이 분야의 모임을 준비하고 있어요.')}</section>`}
function detail(){
  const e=db.events.find(e=>e.id===selected);
  if(!e)return `${header('모임 상세')} ${empty('모임을 찾을 수 없어요.')}`;
  const a=db.applications.find(a=>a.event_id===e.id&&a.status!=='cancelled');
  const bookCover=coverImage(e,true);
  const dateLabel=date(e.date);
  const deposit='5,000원';
  return `${header('모임 상세')}
    <section class="detail-hero" style="--category-background:${palette(e)[0]};--category-accent:${palette(e)[1]}">
      <img class="detail-hero-image" src="${categoryAsset(e,'hero')}" alt="" aria-hidden="true">
      <div class="detail-hero-shade"></div>
      <button class="detail-share-button" type="button" onclick="shareEvent('${e.id}')" aria-label="이 모임 공유">${icon('share',17)}<span>공유</span></button>
      <div class="detail-hero-copy">
        <span class="detail-category">${esc(categoryTitle(e))}</span>
        <h1>${esc(e.book?`『${e.book}』`:e.title)}</h1>
        <p class="detail-event-name"><span>모임</span><b>${esc(e.title)}</b></p>
        <span class="detail-rule"></span>
      </div>
    </section>
    <section class="detail-summary" aria-label="모임 정보">
      <div class="detail-summary-item">${icon('calendar',22)}<p><small>날짜와 시간</small><b>${esc(dateLabel)}</b><span>${time(e.date)}${e.end_time?' – '+esc(e.end_time):''}</span></p></div>
      <a class="detail-summary-item detail-place-link" href="${mapUrl(e)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(placeName(e))} 네이버 지도에서 열기">${icon('pin',22)}<p><small>모임 장소</small><b>${esc(placeName(e))}</b>${placeAddress(e)?`<span class="detail-address">${esc(placeAddress(e))}</span>`:''}<span class="detail-map-link">지도에서 보기 ↗</span></p></a>
      <div class="detail-summary-item">${icon('cup',22)}<p><small>참여 비용</small><b>무료</b><span>참여보증금 ${deposit}</span></p></div>
    </section>
    <section class="content detail-content">
      <div class="detail-section detail-book-section">
        <h2 class="detail-section-title">함께 읽을 책</h2>
        <div class="detail-book-card ${bookCover?'has-cover':''}">
          ${bookCover?`<div class="detail-book-cover">${bookCover}</div>`:''}
          <div class="detail-book-copy"><h3>${esc(e.book?`『${e.book}』`:e.title)}</h3>${e.author?`<p class="detail-book-author">저자 · ${esc(e.author)}</p>`:''}${e.book_description?`<p class="detail-book-description">${esc(e.book_description)}</p>`:'<p class="detail-book-description book-description-empty">책의 내용과 함께 나누고 싶은 지점을 소개합니다.</p>'}</div>
        </div>
        ${e.yes24_url?`<a class="edition-link" href="${esc(e.yes24_url)}" target="_blank" rel="noopener noreferrer">YES24에서 책 보기 ↗</a>`:coverLibrary[e.book]?`<a class="edition-link" href="${coverLibrary[e.book].url}" target="_blank" rel="noopener noreferrer">표지 판본 · ${esc(coverLibrary[e.book].edition)} ↗</a><p class="edition-note">표지는 예시 판본입니다. 가지고 계신 책으로 함께 읽어도 좋아요.</p>`:''}
      </div>
      <div class="detail-section">
        <h2 class="detail-section-title">모임 소개</h2>
        <div class="detail-intro">
          <p class="copy">${esc(e.description||'함께 책을 읽고, 생각과 마음을 나누는 시간입니다.')}</p>
        </div>
      </div>
      <div class="detail-section">
        <h2 class="detail-section-title">함께 나눌 이야기</h2>
        <div class="discussion-prompts">
          <p><span>1</span>책에서 가장 오래 마음에 남은 문장은 무엇인가요?</p>
          <p><span>2</span>그 문장이 내 경험이나 지금의 삶과 어떻게 이어지나요?</p>
          <p><span>3</span>함께 읽은 사람들의 생각 중 새롭게 발견한 점은 무엇인가요?</p>
        </div>
      </div>
      <div class="detail-section">
        <h2 class="detail-section-title">참여 안내</h2>
        <ul class="detail-guide">
          <li><strong>신청 승인 후 24시간 이내</strong> 참여보증금을 입금해 주세요.</li>
          <li>모임 참석 시 <strong>종료 후 전액 환불</strong>됩니다.</li>
          <li><strong>모임 2일 전까지 취소</strong>하면 전액 환불되며, <strong>하루 전·당일 취소 또는 노쇼</strong> 시 보증금 전액을 <strong>어려운 이웃에게 기부</strong>합니다.</li>
          <li>운영자 사정으로 모임이 취소되면 <strong>전액 환불</strong>됩니다.</li>
        </ul>
      </div>
      <div class="guidance"><b>처음 오시는 분도 환영해요</b><p><strong>완독하지 않아도 괜찮아요.</strong> 마음에 남은 문장이나 질문 하나를 함께 나눠요.</p></div>
      <h2>함께한 분들의 후기</h2>
      ${publicReviews.filter(r=>r.event_id===e.id).map(r=>`<article class="my-card"><b>${'★'.repeat(r.rating)}</b><p>${esc(r.body)}</p><small>${esc(r.users?.nickname||'소요 회원')}</small></article>`).join('')||'<p class="footnote">아직 후기가 없습니다.</p>'}
    </section>
    <div class="bottom-action"><div class="deposit-note"><b>무료</b><small>보증금 ${deposit}</small></div><button class="cta" onclick="${a?"nav('my')":`requestApply('${e.id}')`}" ${!a&&state(e)!=='모집 중'?'disabled':''}>${a?label[a.status]:state(e)==='모집 중'?'모임 신청하기':state(e)} ${icon('arrow',18)}</button></div>`
}
function requestApply(id){sessionStorage.setItem('soyo-intent',id);if(!db.user){nav('login');return}const e=db.events.find(e=>e.id===id);openModal(`<span class="modal-symbol">${icon('book',30)}</span><h2>함께 읽어볼까요?</h2><p>『${esc(e.book)}』<br>${date(e.date)} · ${time(e.date)}</p><div class="guidance">신청을 확인한 뒤 참여 확정 여부와 입금 안내를 알려드려요.<br>참여보증금은 5,000원이며 참석하면 모임 후 전액 환불됩니다.<br>모임 2일 전까지 취소하면 전액 환불되고, 하루 전·당일 취소 또는 노쇼 시 어려운 이웃에게 전액 기부됩니다.</div><label class="formlabel" for="depositor-name">입금자명 (다른 이름으로 입금할 때 · 선택)</label><input class="field" id="depositor-name" name="depositor_name" maxlength="30" autocomplete="name" placeholder="입금 확인에만 사용해요"><label class="consent"><input id="agree" type="checkbox"> 공개 활동에는 닉네임을 사용하고, 입금자명은 운영자만 확인하는 데 동의합니다.</label><button class="cta" onclick="submitApplication('${id}')">이 모임 신청하기 ${icon('arrow',18)}</button>`)}
async function shareEvent(id){const e=db.events.find(x=>x.id===id);if(!e)return;const url=`${location.origin}/share/${shareCode(e)}`,title=e.book?`『${e.book}』 · ${e.title}`:e.title,text=[title,date(e.date)+' · '+placeName(e),'소요살롱에서 함께 만나요.'].filter(Boolean).join('\n');if(navigator.share){try{await navigator.share({title,text,url});return}catch(error){if(error.name==='AbortError')return}}try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(url);else throw Error('clipboard unavailable');toast('모임 공유 링크를 복사했어요.')}catch{const field=document.createElement('textarea');field.value=url;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();if(copied)toast('모임 공유 링크를 복사했어요.');else window.prompt('모임 공유 링크를 복사해 주세요.',url)}}
async function submitApplication(id){if(!$('#agree').checked){toast('신청 안내에 동의해 주세요.');return}await mutate(async()=>{await api('applications','POST',{eventId:id,depositorName:$('#depositor-name')?.value.trim()||''});sessionStorage.removeItem('soyo-intent');closeModal();await reload();nav('success',id)})}
function login(){return `${header('로그인')}<section class="content login-content"><div class="login-illustration"><img src="/images/fox-login.png" alt="소요살롱 여우 로고"><span>hello, soyo.</span></div>${eyebrow('YOUR STORY STARTS HERE')}<h1 class="page-title">반가워요.<br>천천히 시작해요.</h1><p class="copy">카카오 계정으로 간편하게 시작하고<br>마음에 드는 모임에 참여해 보세요.</p><button class="cta kakao" onclick="signIn()"><span class="chat-bubble"></span>카카오로 시작하기</button>${preview?'<p class="preview-note">미리보기에서는 가상 회원으로 로그인합니다.<br>실제 카카오 계정과 연결되지 않습니다.</p>':''}<p class="footnote">닉네임과 모임 신청 내역을 이용합니다.<br><button class="text-button" onclick="nav('privacy')">개인정보 안내</button></p></section>`}
async function signIn(){if(!preview){location.href='/auth/kakao';return}demo.user={id:'demo-user',nickname:'소요 회원'};save();await reload();const intent=sessionStorage.getItem('soyo-intent');if(intent){nav('detail',intent);setTimeout(()=>requestApply(intent),50)}else nav('my')}
function success(){return `${header('신청 완료')}<section class="content success"><span class="success-icon">${icon('check',38)}</span>${eyebrow('SEE YOU SOON')}<h1 class="page-title">신청이 접수되었어요.<br>이제 함께 읽을 차례예요.</h1><p class="copy">신청해 주셔서 감사합니다.<br>운영자가 확인한 뒤 참여 확정 여부와 입금 안내를 드릴게요.</p><div class="guidance">신청 상태는 MY에서 확인해 주세요.<br>지금은 자동 카카오톡 메시지를 보내지 않아요.</div><button class="cta" onclick="nav('my')">내 신청 확인하기 ${icon('arrow',18)}</button><button class="text-button" onclick="nav('events')">다른 모임 둘러보기</button></section>`}
function my(){if(!db.user)return login();let aa=db.applications.filter(a=>myFilter==='전체'||a.status!=='cancelled'&&new Date(db.events.find(e=>e.id===a.event_id)?.date)>new Date());return `${header('나의 소요')}<section class="content"><div class="profile-card"><span class="avatar">${icon('my',27)}</span><div><small>오늘도 반가워요</small><h1>${esc(db.user.nickname)}님 ${icon('book',23)}</h1></div><button class="text-button" onclick="profileEditOpen=!profileEditOpen;render()">${profileEditOpen?'닫기':'닉네임 변경'}</button></div>${profileEditOpen?`<form class="profile-edit" onsubmit="saveNickname(event)"><label class="formlabel" for="profile-nickname">사이트에서 사용할 닉네임</label><input class="field" id="profile-nickname" name="nickname" maxlength="24" minlength="2" value="${esc(db.user.nickname)}" required><small class="hint">후기와 댓글에는 이 닉네임만 표시돼요.</small><button class="cta">닉네임 저장</button></form>`:''}<div class="my-heading"><h2>나의 모임</h2><span>한 권씩, 함께 쌓는 시간</span></div><div class="segmented">${['다가오는','전체'].map(x=>`<button class="${myFilter===x?'on':''}" onclick="myFilter='${x}';render()">${x==='전체'?'전체 내역':x+' 모임'}</button>`).join('')}</div>${aa.length?aa.map(a=>{const e=db.events.find(e=>e.id===a.event_id);return `<article class="my-card"><span class="status ${a.status}">${icon(a.status==='confirmed'?'check':'calendar',13)}${label[a.status]}</span><h3>${esc(e?.book||e?.title||'종료된 모임')}</h3><p>${e?date(e.date)+' · '+time(e.date):''}</p><small>${a.status==='pending'?'운영자가 신청을 확인하고 있어요.':a.status==='confirmed'?'함께 읽는 날에 만나요.':a.status==='waitlist'?'참여 가능한 자리가 생기면 운영자가 확인합니다.':'취소된 신청입니다.'}</small><div class="my-card-actions"><button class="text-button" onclick="nav('detail','${a.event_id}')">모임 보기 ${icon('arrow',15)}</button>${a.status!=='cancelled'?`<button class="cancel-link" onclick="cancelApplication('${a.id}')">신청 취소</button>`:''}</div></article>`}).join(''):empty('아직 신청한 모임이 없어요.<br>함께 읽고 싶은 책을 찾아보세요.')}<button class="cta secondary" onclick="nav('events')">모임 둘러보기 ${icon('arrow',17)}</button><div class="settings-list">${db.admin?'<button onclick="loadAdmin()">운영자 관리 <span>→</span></button>':''}<button onclick="nav('privacy')">개인정보 안내 <span>→</span></button><button onclick="logout()">로그아웃 <span>→</span></button></div></section>`}
async function saveNickname(ev){ev.preventDefault();const nickname=new FormData(ev.target).get('nickname');await mutate(async()=>{const result=await api('me','PATCH',{nickname});db.user.nickname=result.nickname;profileEditOpen=false;render();toast('닉네임을 저장했어요.')})}
function cancelApplication(id){openModal(`<h2>신청을 취소할까요?</h2><p>참석이 어려우시군요.<br>다음에 함께 읽을 날을 기다릴게요.</p><button class="cta" onclick="confirmCancel('${id}')">신청 취소하기</button><button class="cta secondary" onclick="closeModal()">신청 유지하기</button>`)}
async function confirmCancel(id){await mutate(async()=>{await api('applications/cancel','POST',{id});closeModal();await reload();toast('신청을 취소했어요.')})}
async function logout(){await mutate(async()=>{await api('logout','POST');await reload();nav('home')})}
function setRecordTab(tab){recordTab=tab;recordFormOpen=false;render()}
function toggleRecordForm(){recordFormOpen=!recordFormOpen;render()}
function recordPhotoInput(){return `<label class="formlabel">사진 (최대 3장)</label><input class="field" type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple onchange="previewRecordPhotos(event)"><div id="record-photo-preview" class="record-photo-preview"></div>`}
function previewRecordPhotos(ev){const files=[...ev.target.files||[]];if(files.length>3){ev.target.value='';toast('사진은 최대 3장까지 선택할 수 있어요.');return}const box=$('#record-photo-preview');if(box)box.innerHTML=files.map(f=>`<img src="${URL.createObjectURL(f)}" alt="선택한 사진 미리보기">`).join('')}
async function uploadRecordPhotos(files){if(!files.length)return [];if(files.length>3)throw Error('사진은 최대 3장까지 올릴 수 있어요.');const out=[];for(const file of files){if(file.size>5*1024*1024)throw Error('사진은 한 장당 5MB 이하로 선택해 주세요.');const r=await fetch('/api/record-photos',{method:'POST',credentials:'same-origin',headers:{'content-type':file.type},body:file});const j=await r.json();if(!r.ok)throw Error(j.error||'사진 업로드에 실패했어요.');out.push(j.url)}return out}
function readingCommentsMarkup(note){const comments=window.noteComments[note.id]||[];return `<div class="reading-comments">${comments.length?comments.map(c=>`<div class="reading-comment"><p>${esc(c.body)}</p><small>${esc(c.users?.nickname||'소요 회원')}</small>${db.user&&c.user_id===db.user.id?`<button onclick="deleteReadingNoteComment('${c.id}')" aria-label="댓글 삭제">삭제</button>`:''}</div>`).join(''):'<p class="comments-empty">첫 댓글을 남겨보세요.</p>'}${db.user?`<form class="comment-form" onsubmit="postReadingNoteComment(event,'${note.id}')"><input class="field" name="body" maxlength="600" placeholder="따뜻한 한마디를 남겨주세요" required><button class="tiny">등록</button></form>`:'<p class="comments-login">댓글을 남기려면 로그인해 주세요.</p>'}</div>`}
async function toggleReadingNoteLike(id){if(!db.user){toast('로그인 후 좋아요를 누를 수 있어요.');return}const note=publicReadingNotes.find(n=>n.id===id);if(!note)return;const liked=!note.liked_by_me;try{const result=await api(`reading-notes/${id}/likes`,'POST',{liked});note.liked_by_me=result.liked;note.likes_count=result.likes_count;render()}catch(e){toast(e.message)}}
async function toggleReadingNoteComments(id){if(expandedReadingNotes.has(id)){expandedReadingNotes.delete(id);render();return}expandedReadingNotes.add(id);try{window.noteComments[id]=await api(`reading-notes/${id}/comments`)}catch{window.noteComments[id]=[]}render()}
async function postReadingNoteComment(ev,id){ev.preventDefault();const body=new FormData(ev.target).get('body');try{const comment=await api(`reading-notes/${id}/comments`,'POST',{body});window.noteComments[id]=[...(window.noteComments[id]||[]),comment];const note=publicReadingNotes.find(n=>n.id===id);if(note)note.comments_count=(note.comments_count||0)+1;render()}catch(e){toast(e.message)}}
async function deleteReadingNoteComment(id){const note=publicReadingNotes.find(n=>(window.noteComments[n.id]||[]).some(c=>c.id===id));try{await api(`reading-note-comments/${id}`,'DELETE');for(const key of Object.keys(window.noteComments))window.noteComments[key]=window.noteComments[key].filter(c=>c.id!==id);if(note)note.comments_count=Math.max(0,(note.comments_count||1)-1);render()}catch(e){toast(e.message)}}
function reviewsPage(){
 const mine=r=>db.user&&r.user_id===db.user.id;
 const actions=(kind,r)=>mine(r)?`<div class="record-actions"><button type="button" onclick="editRecord('${kind}','${r.id}')">수정</button><button type="button" class="danger" onclick="deleteRecord('${kind}','${r.id}')">삭제</button></div>`:'';
 const photos=arr=>(arr||[]).map(src=>`<img src="${esc(src)}" alt="첨부 사진" loading="lazy">`).join('');
 const reviewForm=db.user&&db.applications.some(a=>a.status==='confirmed')?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'후기 남기기 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postReview(event)"><label class="formlabel" for="review-event">참여한 모임</label><select class="field" id="review-event" name="event_id" required>${db.applications.filter(a=>a.status==='confirmed').map(a=>`<option value="${a.event_id}">${esc(db.events.find(e=>e.id===a.event_id)?.title||'모임')}</option>`).join('')}</select><label class="formlabel" for="review-rating">오늘의 여운</label><select class="field" id="review-rating" name="rating"><option value="5">★★★★★ · 오래 기억하고 싶어요</option><option value="4">★★★★ · 참 좋았어요</option><option value="3">★★★ · 편안한 시간이었어요</option><option value="2">★★ · 아쉬운 점이 있었어요</option><option value="1">★ · 의견을 나누고 싶어요</option></select><label class="formlabel" for="review-body">후기</label><textarea class="field" id="review-body" name="body" rows="4" maxlength="3000" placeholder="기억에 남은 문장이나 함께 나눈 이야기를 적어주세요." required></textarea>${recordPhotoInput()}<div class="record-form-foot"><span>참여가 확정된 회원만 작성할 수 있어요.</span><button class="cta">후기 남기기</button></div></form>`:''}`:db.user?'<div class="record-note">참여가 확정된 모임이 생기면 후기를 남길 수 있어요.</div>':'<div class="record-note">로그인 후 참여한 모임의 후기를 남길 수 있어요.</div>';
 const bookForm=db.user?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'서평 쓰기 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postBookReview(event)"><label class="formlabel" for="book-title">책 제목</label><input class="field" id="book-title" name="title" maxlength="160" placeholder="책 제목을 적어주세요" required><label class="formlabel" for="book-body">서평</label><textarea class="field" id="book-body" name="body" rows="4" maxlength="3000" placeholder="책을 다 읽고 마음에 남은 생각을 적어주세요." required></textarea>${recordPhotoInput()}<div class="record-form-foot"><span>최대 3,000자 · 사진 3장</span><button class="cta">서평 올리기</button></div></form>`:''}`:'<div class="record-note">로그인하면 책을 다 읽고 난 뒤의 감상을 나눌 수 있어요.</div>';
 const readingForm=db.user?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'읽는 중 기록 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postReadingNote(event)"><label class="formlabel" for="reading-title">지금 읽고 있는 책</label><input class="field" id="reading-title" name="title" maxlength="160" placeholder="책 제목" required><label class="formlabel" for="reading-body">잠깐 남기는 생각</label><textarea class="field" id="reading-body" name="body" rows="3" maxlength="1600" placeholder="읽다가 만난 문장이나 문득 든 생각을 가볍게 적어주세요." required></textarea>${recordPhotoInput()}<div class="record-form-foot"><span>짧은 메모 · 최대 1,600자 · 사진 3장</span><button class="cta">기록 올리기</button></div></form>`:''}`:'<div class="record-note">로그인 후 지금 읽고 있는 책과 작은 생각을 나눌 수 있어요.</div>';
 const privateForm=db.user?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'나만의 기록 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postPrivateNote(event)"><label class="formlabel" for="private-title">책 제목 (선택)</label><input class="field" id="private-title" name="title" maxlength="160" placeholder="책이나 모임 이름을 적어도 좋아요"><label class="formlabel" for="private-body">나만 볼 기록</label><textarea class="field" id="private-body" name="body" rows="4" maxlength="3000" placeholder="떠오른 생각이나 아직 나누고 싶지 않은 문장을 적어두세요." required></textarea><div class="record-form-foot"><span>나만 볼 수 있어요 · 최대 3,000자</span><button class="cta">기록 저장</button></div></form>`:''}`:'<div class="record-note">로그인 후 나만 볼 수 있는 기록을 저장할 수 있어요.</div>';
 const reviewContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">✦</span><div><h2>모임 후기</h2><p>함께한 자리에서 기억에 남은 순간</p></div></div>${reviewForm}<div class="record-list">${publicReviews.map(r=>`<article class="record-card"><div class="record-card-top"><span class="record-tag">${esc(r.events?.title||'함께한 모임')}</span><span class="record-stars">${'★'.repeat(r.rating)}<i>${'★'.repeat(5-r.rating)}</i></span></div><p>${esc(r.body)}</p><div class="record-photos">${photos(r.photos)}</div><div class="record-card-foot"><small>${esc(r.users?.nickname||'소요 회원')} · ${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('review',r)}</div></article>`).join('')||'<div class="record-empty">첫 모임 후기를 기다리고 있어요.<br>함께한 기억을 나눠주세요.</div>'}</div></section>`;
 const readingContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">⌁</span><div><h2>읽는 중</h2><p>완독 전에도, 책 곁에서 만난 작은 생각</p></div></div>${readingForm}<div class="record-list">${publicReadingNotes.map(r=>`<article class="record-card"><span class="record-tag">${esc(r.book_title)}</span><p>${esc(r.body)}</p><div class="record-photos">${photos(r.photos)}</div><div class="record-card-foot"><small>${esc(r.users?.nickname||'소요 회원')} · ${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('reading',r)}</div><div class="reading-note-social"><button class="social-button ${r.liked_by_me?'liked':''}" onclick="toggleReadingNoteLike('${r.id}')" aria-pressed="${!!r.liked_by_me}">♡ <span>좋아요</span> <b>${r.likes_count||0}</b></button><button class="social-button" onclick="toggleReadingNoteComments('${r.id}')">댓글 <b>${r.comments_count||0}</b></button></div>${expandedReadingNotes.has(r.id)?readingCommentsMarkup(r):''}</article>`).join('')||'<div class="record-empty">지금 읽고 있는 책과<br>문득 떠오른 생각을 나눠보세요.</div>'}</div></section>`;
 const privateContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">◉</span><div><h2>나만 보기</h2><p>아직 나누고 싶지 않은 생각을 조용히 적어두세요</p></div></div><div class="record-note private-notice">🔒 이 기록은 본인 계정에서만 볼 수 있어요.</div>${privateForm}<div class="record-list">${privateNotes.map(r=>`<article class="record-card private-record"><span class="record-tag">${esc(r.book_title||'나의 기록')}</span><p>${esc(r.body)}</p><div class="record-card-foot"><small>${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('private',r)}</div></article>`).join('')||'<div class="record-empty">아직 비공개 기록이 없어요.<br>마음에 남은 생각을 나만의 공간에 적어보세요.</div>'}</div></section>`;
 const bookContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">▤</span><div><h2>책 서평</h2><p>책을 덮은 뒤에도 이어지는 생각</p></div></div>${bookForm}<div class="record-list">${(window.bookReviews||[]).map(r=>`<article class="record-card"><span class="record-tag">${esc(r.book_title)}</span><p>${esc(r.body)}</p><div class="record-photos">${photos(r.photos)}</div><div class="record-card-foot"><small>${esc(r.users?.nickname||'소요 회원')} · ${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('book',r)}</div></article>`).join('')||'<div class="record-empty">아직 서평이 없어요.<br>책을 다 읽고 첫 감상을 남겨보세요.</div>'}</div></section>`;
 return `${header('소요의 기록')}<section class="content records-page"><div class="records-intro"><span class="eyebrow">SOYO JOURNAL</span><h1 class="page-title">읽고, 나누고,<br>마음에 남기기.</h1><p class="subcopy">함께한 시간과 읽는 동안의 생각, 책을 덮은 뒤의 감상을 모아요.</p></div><div class="record-tabs" role="tablist" aria-label="기록 종류"><button role="tab" aria-selected="${recordTab==='review'}" class="${recordTab==='review'?'active':''}" onclick="setRecordTab('review')">모임 후기 <span>${publicReviews.length}</span></button><button role="tab" aria-selected="${recordTab==='reading'}" class="${recordTab==='reading'?'active':''}" onclick="setRecordTab('reading')">읽는 중 <span>${publicReadingNotes.length}</span></button><button role="tab" aria-selected="${recordTab==='book'}" class="${recordTab==='book'?'active':''}" onclick="setRecordTab('book')">서평 <span>${(window.bookReviews||[]).length}</span></button><button role="tab" aria-selected="${recordTab==='private'}" class="${recordTab==='private'?'active':''}" onclick="setRecordTab('private')">나만 보기</button></div>${recordTab==='review'?reviewContent:recordTab==='reading'?readingContent:recordTab==='private'?privateContent:bookContent}</section>`
}
function editRecord(kind,id){const list=kind==='review'?publicReviews:kind==='book'?(window.bookReviews||[]):kind==='private'?privateNotes:publicReadingNotes,r=list.find(x=>x.id===id);if(!r)return;const title=kind==='review'?'후기':kind==='reading'?'읽는 중 기록':kind==='private'?'나만의 기록':'서평';openModal(`<h2>${title} 수정</h2>${kind!=='review'?`<label class="formlabel">책 제목 (선택)</label><input class="field" id="edit-title" maxlength="160" value="${esc(r.book_title||'')}">`:''}${kind==='review'?`<label class="formlabel">별점</label><select class="field" id="edit-rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${r.rating===n?'selected':''}>${'★'.repeat(n)}</option>`).join('')}</select>`:''}<label class="formlabel">내용</label><textarea class="field" id="edit-body" rows="5" maxlength="${kind==='reading'?1600:kind==='private'?3000:3000}">${esc(r.body)}</textarea>${kind==='private'?'':`<label class="formlabel">기존 사진</label><div id="edit-photo-list" class="record-photo-preview">${(r.photos||[]).map((src,i)=>`<span><img src="${esc(src)}" alt="첨부 사진"><button type="button" onclick="removeEditPhoto(${i})">빼기</button></span>`).join('')||'사진 없음'}</div><label class="formlabel">사진 추가 (최대 3장까지)</label><input class="field" id="edit-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="previewRecordPhotos(event)">`}<button class="cta" onclick="saveRecord('${kind}','${id}')">수정 내용 저장</button>`);window.editingRecord={kind,id,photos:[...(r.photos||[])]}}
function removeEditPhoto(i){window.editingRecord.photos.splice(i,1);const box=$('#edit-photo-list');box.innerHTML=window.editingRecord.photos.map((src,n)=>`<span><img src="${esc(src)}" alt="첨부 사진"><button type="button" onclick="removeEditPhoto(${n})">빼기</button></span>`).join('')||'사진 없음'}
async function saveRecord(kind,id){const body=$('#edit-body').value.trim(),data=kind==='review'?{body,rating:Number($('#edit-rating').value)}:{body,title:$('#edit-title').value.trim()},endpoint=kind==='review'?'reviews/':kind==='book'?'book-reviews/':kind==='private'?'private-notes/':'reading-notes/';await mutate(async()=>{if(kind!=='private'){const added=await uploadRecordPhotos([...($('#edit-photos')?.files||[])]);data.photos=[...(window.editingRecord?.photos||[]),...added];if(data.photos.length>3)throw Error('사진은 최대 3장까지 보관할 수 있어요.')}await api(endpoint+id,'PATCH',data);closeModal();await reload();toast('기록을 수정했어요.')})}
async function deleteRecord(kind,id){const title=kind==='review'?'후기':kind==='reading'?'읽기 기록':'서평';openModal(`<h2>${title}를 삭제할까요?</h2><p>삭제한 기록은 되돌릴 수 없습니다.</p><button class="cta" onclick="confirmDeleteRecord('${kind}','${id}')">삭제하기</button><button class="cta secondary" onclick="closeModal()">취소</button>`)}
async function confirmDeleteRecord(kind,id){const endpoint=kind==='review'?'reviews/':kind==='book'?'book-reviews/':kind==='private'?'private-notes/':'reading-notes/';await mutate(async()=>{await api(endpoint+id,'DELETE');closeModal();await reload();toast('기록을 삭제했어요.')})}
async function postReview(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),d={eventId:f.event_id,rating:Number(f.rating),body:f.body};await mutate(async()=>{d.photos=await uploadRecordPhotos([...ev.target.querySelector('[name=photos]').files]);await api('reviews','POST',d);await reload();toast('모임 후기를 남겼어요.')})}
async function postBookReview(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));await mutate(async()=>{d.photos=await uploadRecordPhotos([...ev.target.querySelector('[name=photos]').files]);await api('book-reviews','POST',d);await reload();toast('서평을 올렸어요.')})}
async function postReadingNote(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));await mutate(async()=>{d.photos=await uploadRecordPhotos([...ev.target.querySelector('[name=photos]').files]);await api('reading-notes','POST',d);recordFormOpen=false;await reload();toast('읽기 기록을 올렸어요.')})}
async function postPrivateNote(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));await mutate(async()=>{await api('private-notes','POST',d);recordFormOpen=false;await reload();toast('나만의 기록을 저장했어요.')})}
function about(){return `${header('소요살롱 이야기')}<section class="content about"><div class="about-symbol">逍遙<span>soyo salon</span></div>${eyebrow('READ SLOWLY, CONNECT DEEPLY')}<h1 class="page-title">서로 다른 생각이<br>만나는 작은 자리.</h1><p class="copy">소요는 ‘자유롭게 거닐다’라는 뜻입니다.<br>책 속을 거닐다 만난 생각들을<br>편안하게 꺼내놓는 시간을 만들고 싶어요.</p><div class="about-values">${[['01','잘 읽는 것보다, 함께 읽기','완독하지 않아도 괜찮아요. 읽은 만큼의 이야기를 가져와 주세요.'],['02','정답보다, 서로의 질문','한두 문장을 소리 내어 읽고, 나누고 싶은 질문 하나를 꺼내요.'],['03','낯선 사이에서, 반가운 사이로','대구 카페에서 만나요. 차 한 잔과 함께 천천히 가까워져요.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><button class="cta" onclick="nav('events')">우리, 함께 읽어요 ${icon('arrow',18)}</button></section>`}
function privacy(){return `${header('개인정보 안내')}<section class="content"><h1 class="page-title">소중한 정보는<br>필요한 만큼만.</h1><p class="copy">소요살롱은 로그인과 모임 신청 관리를 위해 카카오 회원 식별값, 공개용 닉네임, 신청한 모임과 상태, 신청 일시를 저장합니다. 카카오 비밀번호와 휴대전화 번호는 저장하지 않습니다. 입금자명은 신청자가 선택해 입력하며, 입금 확인을 위해 운영자만 볼 수 있습니다.\n\n모임 후기와 ‘읽는 중’ 기록, 사진과 댓글은 다른 방문자에게 공개됩니다. ‘나만 보기’에 저장한 글은 본인 계정에서만 확인할 수 있습니다. 참가 인원과 다른 회원의 신청 내역은 공개하지 않으며, 운영자만 신청을 확인하고 승인할 수 있습니다.</p><div class="guidance">${preview?'현재 화면은 미리보기입니다. 가상 신청 정보는 이 브라우저에만 저장됩니다. 미리보기 도구에서 초기화할 수 있습니다.':'정보 삭제 요청은 모임 운영자에게 문의해 주세요.'}</div><p class="footnote">운영 공개 전 책임자·문의처·보유 기간 등 실제 운영 방침을 확정해야 합니다.</p></section>`}
async function loadAdmin(){nav('admin')}
function admin(){if(!db.admin)return `${header('운영자')} ${empty('접근 권한이 없습니다.')}`;return `${header('운영자 관리')}<section class="content">${eyebrow('SALON DESK')}<h1 class="page-title">좋은 만남을 준비하는 시간.</h1><p class="subcopy">신청을 확인하고<br>다음 모임을 차분히 준비해요.</p><h2>신청 관리</h2>${adminApplications.length?adminApplications.map(a=>`<article class="my-card"><div class="card-meta"><b>${esc(a.users?.nickname||'회원')}</b><span class="status ${a.status}">${label[a.status]}</span></div><h3>${esc(a.events?.title||'모임')}</h3><small class="admin-private-field">입금자명 · ${esc(a.depositor_name||'미입력')}</small><div class="admin-actions">${[['confirmed','승인'],['waitlist','대기'],['cancelled','취소']].map(([s,t])=>`<button class="tiny ${s==='confirmed'?'approve':''}" ${a.status===s?'disabled':''} onclick="setStatus('${a.id}','${s}')">${t}</button>`).join('')}</div></article>`).join(''):empty('아직 접수된 신청이 없어요.')}<div class="section-head admin-heading"><h2>모임 관리</h2><button class="text-button" onclick="nav('newEvent')">+ 모임 만들기</button></div>${db.events.map(e=>`<article class="my-card"><span class="mini-category">${esc(e.category)} · ${state(e)}</span><h3>${esc(e.book||e.title)}</h3><p>${date(e.date)}</p><button class="tiny" onclick="editEvent('${e.id}')">수정</button><button class="tiny" onclick="toggleEvent('${e.id}','${e.status==='closed'?'open':'closed'}')">${e.status==='closed'?'모집 재개':'모집 마감'}</button></article>`).join('')}<h2>모임 후기</h2>${publicReviews.map(r=>`<article class="my-card"><b>${esc(r.events?.title||'모임')} · ${'★'.repeat(r.rating)}</b><p>${esc(r.body)}</p><small>${esc(r.users?.nickname||'회원')}</small></article>`).join('')||empty('아직 후기가 없어요.')}<h2>서평</h2>${(window.adminBookReviews||[]).map(r=>`<article class="my-card"><b>${esc(r.book_title)}</b><p>${esc(r.body)}</p><small>${esc(r.users?.nickname||'회원')}</small></article>`).join('')||empty('아직 서평이 없어요.')}</section>`}
function newEvent(){editingEventId=null;return eventForm(null)}
function editEvent(id){editingEventId=id;nav('editEvent',id)}
function eventForm(e){if(!db.admin)return admin();const editing=!!e;const val=(k)=>esc(e?.[k]??'');const dt=e?.date?new Date(new Date(e.date).getTime()+9*60*60*1000).toISOString().slice(0,16):'';return `${header(editing?'모임 수정':'새 모임 만들기')}<section class="content"><h1 class="page-title">${editing?'모임 정보를 수정해요.':'다음 이야기를 열어요.'}</h1><form id="event-form" onsubmit="saveEvent(event)">${[['title','모임 제목','text'],['book','함께 읽을 책','text'],['author','책 저자','text'],['place','장소명','text'],['place_address','도로명 주소 (선택)','text'],['date','시작 일시 (한국 시간)','datetime-local'],['end','종료 시간','time'],['capacity','정원 · 운영자만 확인','number']].map(([name,label,type])=>`<label class="formlabel" for="${name}">${label}</label><input class="field" id="${name}" name="${name}" type="${type}" value="${name==='date'?dt:val(name==='end'?'end_time':name)}" ${['title','place','date','capacity'].includes(name)?'required':''} ${name==='place_address'?'placeholder="예: 대구광역시 중구 동덕로 00"':''} ${name==='capacity'?'min="1" max="100" step="1" value="'+(e?.capacity||6)+'"':''}>${name==='place_address'?'<small class="hint">주소를 입력하면 지도에서 정확한 장소를 찾기 쉬워요.</small>':''}`).join('')}<label class="formlabel" for="category">모임 분야</label><select class="field" id="category" name="category">${['문학','철학','명상','글쓰기','원서','자유모임'].map(c=>`<option ${e?.category===c?'selected':''}>${c}</option>`).join('')}</select><label class="formlabel" for="cover">책 표지 이미지</label><input class="field" id="cover" type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadCover(event)"><input type="hidden" name="cover_url" value="${val('cover_url')}"><small class="footnote">JPG, PNG, WebP · 5MB 이하</small><label class="formlabel" for="book_description">책 소개 (선택)</label><textarea class="field" id="book_description" name="book_description" rows="5" maxlength="3000" placeholder="책의 내용이나 모임에서 함께 살펴볼 주제를 소개해 주세요.">${val('book_description')}</textarea><label class="formlabel" for="yes24_url">YES24 책 링크 (선택)</label><input class="field" id="yes24_url" name="yes24_url" type="url" inputmode="url" placeholder="https://www.yes24.com/..." value="${val('yes24_url')}"><small class="hint">해당 책의 YES24 상세 페이지 주소를 붙여 넣어 주세요.</small><label class="formlabel" for="description">모임 소개</label><textarea class="field" id="description" name="description" rows="7">${val('description')}</textarea><button class="cta" type="submit">${editing?'수정 내용 저장':'새 모임 등록하기'}</button></form></section>`}
function editEventPage(){return eventForm(db.events.find(e=>e.id===editingEventId))}
async function uploadCover(event){const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast('이미지는 5MB 이하로 선택해 주세요.');return}await mutate(async()=>{const r=await fetch('/api/admin/covers',{method:'POST',credentials:'same-origin',headers:{'content-type':file.type},body:file});const j=await r.json();if(!r.ok)throw Error(j.error||'표지 업로드에 실패했어요.');document.querySelector('[name=cover_url]').value=j.url;toast('책 표지를 올렸어요.')})}
async function saveEvent(event){event.preventDefault();const data=Object.fromEntries(new FormData(event.target));data.capacity=Number(data.capacity);data.date=new Date(data.date+':00+09:00').toISOString();await mutate(async()=>{if(editingEventId)await api('admin/events/'+editingEventId,'PATCH',data);else await api('admin/events','POST',data);await reload();editingEventId=null;nav('admin');toast('모임 정보를 저장했어요.')})}
async function setStatus(id,status){await mutate(async()=>{await api('admin/applications/status','POST',{id,status});await reload();render();toast('신청 상태를 변경했어요.')})}
async function toggleEvent(id,status){await mutate(async()=>{await api('admin/events/status','POST',{id,status});await reload();toast('모집 상태를 변경했어요.')})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function mutate(fn){if(busy)return;busy=true;document.body.classList.add('busy');try{await fn()}catch(e){toast(e.message)}finally{busy=false;document.body.classList.remove('busy')}}
let previousFocus;function openModal(html){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="신청 안내"><button class="modal-close icon-button" aria-label="닫기" onclick="closeModal()">${icon('close')}</button>${html}</section></div>`;setTimeout(()=>$('.modal button')?.focus(),0)}
function closeModal(){$('#modal-root').innerHTML='';previousFocus?.focus();previousFocus=null}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();const m=$('.modal');if(m&&e.key==='Tab'){const f=[...m.querySelectorAll('button,input,a')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
async function demoAdmin(){demo.user={id:'demo-user',nickname:'소요 회원'};demo.admin=!demo.admin;save();await reload();if(demo.admin)await loadAdmin();else nav('my')}
function resetDemo(){openModal('<h2>미리보기를 초기화할까요?</h2><p>가상 신청 내역과 추가한 모임이 초기화됩니다.</p><button class="cta" onclick="localStorage.removeItem(\'soyo-preview-v2\');sessionStorage.removeItem(\'soyo-intent\');location.href=location.pathname">초기화하기</button>')}
function render(){document.body.classList.toggle('home-page',route==='home');document.body.classList.toggle('detail-page',route==='detail');$('#app').innerHTML=({home,events,detail,login,success,my,about,privacy,admin,newEvent,editEvent:editEventPage,reviews:reviewsPage}[route]||home)()+tabs();if(preview){$('#studio').innerHTML=`<div class="preview-ribbon"><span>미리보기 · 예시 일정</span><div><button onclick="demoAdmin()">${demo.admin?'회원 보기':'관리자 체험'}</button><button onclick="resetDemo()">초기화</button></div></div>`}}
reload().then(()=>{if(new URLSearchParams(location.search).has('logged_in')){history.replaceState(null,'',location.pathname+location.hash);const id=sessionStorage.getItem('soyo-intent');if(id){nav('detail',id);setTimeout(()=>requestApply(id),50)}else nav('my')}}).catch(()=>{$('#app').innerHTML=`${header('소요살롱')}<div class="empty"><h2>잠시 연결이 어려워요.</h2><p>잠시 후 다시 시도해 주세요.</p><button class="cta" onclick="location.reload()">다시 불러오기</button></div>`});
